/** Look up a frame by its shoot number. */
export function p(id: number): Photo {
  const found = PHOTOS[id];
  if (!found) throw new Error(`Unknown photo #${id}`);
  return found;
}

/** Look up several frames at once. */
export const ps = (...ids: number[]): Photo[] => ids.map(p);
